add_action( 'init', 'perfectpixel_disable_embeds', 9999 );
add_filter( 'embed_oembed_discover', '__return_false' );
add_filter( 'tiny_mce_plugins', 'perfectpixel_disable_embeds_tinymce' );
add_action( 'template_redirect', 'perfectpixel_disable_embeds_endpoint', 1 );

function perfectpixel_disable_embeds() {
	remove_action( 'wp_head', 'wp_oembed_add_discovery_links' );
	remove_action( 'wp_head', 'wp_oembed_add_host_js' );
	remove_action( 'rest_api_init', 'wp_oembed_register_route' );
	remove_filter( 'oembed_dataparse', 'wp_filter_oembed_result', 10 );
	remove_filter( 'pre_oembed_result', 'wp_filter_pre_oembed_result', 10 );
	remove_filter( 'embed_oembed_html', 'wp_maybe_enqueue_oembed_host_js' );
}

function perfectpixel_disable_embeds_tinymce( $plugins ) {
	return array_diff( $plugins, array( 'wpembed' ) );
}

// /post-name/embed/ pages exist only to be shown inside other sites.
function perfectpixel_disable_embeds_endpoint() {
	if ( is_embed() ) {
		global $wp_query;
		$wp_query->set_404();
		status_header( 404 );
		nocache_headers();
	}
}
